import unicodedata
def key(s): return unicodedata.normalize('NFD',s).encode('ascii','ignore').decode().lower()
L.sort(key=lambda x:key(x[0]))
out=['<!-- ===================== LEXIQUE ===================== -->','<section class="chapter lexique">','  <div class="chapter-head">','    <span class="kicker">ANNEXE · LEXIQUE</span>','    <h1>Lexique : les mots du terrain</h1>','    <p class="lead">Chaque mot en simple, en pro, et en anglais (utile pour la diaspora qui vit dans un pays anglophone).</p>','  </div>']
cur=''
for m,en,s,p in L:
    l=key(m)[0].upper()
    if l!=cur:
        cur=l; out.append(f'  <div class="lex-letter">{l}</div>')
    out.append(f'  <div class="lex"><span class="m">{m}</span> <span class="en">(anglais : {en})</span><div class="s">{s}</div><div class="pro">{p}</div></div>')
out.append('</section>')
open('/home/user/REMPRES/e-book/02-terrain-construction/livre/src/book/70-lexique.html','w').write('\n'.join(out)+'\n')
print(len(L))
